import json,numpy as np
from PIL import Image
p='/app/runs/food_packing3_boxes/008_obs'; rgb=np.array(Image.open(p+'/last/egocentric_mirrored_camera.jpg')); d=np.load(p+'/last_depth_egocentric_mirrored_camera.npy'); c=json.load(open(p+'/meta.json'))['cameras']['egocentric_mirrored_camera']; K=np.array(c['intrinsic_cv']); E=np.array(c['extrinsic_cv']); R=E[:,:3]; t=E[:,3]
y,x=np.mgrid[:rgb.shape[0],:rgb.shape[1]]; roi=(x>50)&(x<195)&(y>120)&(y<280)
r,g,b=[rgb[:,:,i].astype(float) for i in range(3)]
for name,col in [('yellow',(r>g*1.15)&(g>b*1.4)&(r>130)&(g>100)),('white',(r>150)&(g>150)&(b>130)&(np.abs(r-g)<60)),('saturated',(r>130)&(g>100)&(b<110)),('all',(r>130)&(g>100)&(b<150))]:
 mask=roi&col&(d>0); yy,xx=np.where(mask); pix=np.stack([xx,yy,np.ones_like(xx)],axis=0); cam=np.linalg.inv(K)@pix*d[mask]; w=np.linalg.inv(R)@(cam-t[:,None]);
 for zmin in [0.01,0.02]:
  q=w[:,w[2]>zmin];
  if q.shape[1]:print(name,zmin,q.shape[1],'xy q10/50/90',np.percentile(q[:2].T,[10,50,90],axis=0).round(3),'z',np.percentile(q[2],[10,50,90]).round(3),'pix',np.percentile(np.stack([xx[w[2]>zmin],yy[w[2]>zmin]],1),[10,50,90],axis=0))
