import json,numpy as np
from PIL import Image
p='/app/runs/food_packing3_boxes/024_obs'; im=np.array(Image.open(p+'/last/egocentric_mirrored_camera.jpg')); d=np.load(p+'/last_depth_egocentric_mirrored_camera.npy'); c=json.load(open(p+'/meta.json'))['cameras']['egocentric_mirrored_camera']; K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:,:3];t=E[:,3]
y,x=np.mgrid[:im.shape[0],:im.shape[1]]; r,g,b=[im[:,:,i].astype(float) for i in range(3)]; roi=(x>175)&(x<285)&(y>55)&(y<280); mask=roi&(r>100)&(r>g*1.25)&(r>b*1.25)&(g<160)&(d>0)
yy,xx=np.where(mask); z=d[mask]; cam=np.linalg.inv(K)@np.stack([xx,yy,np.ones_like(xx)])*z; w=np.linalg.inv(R)@(cam-t[:,None]);
for a,bb in [(-.01,.015),(.015,.05),(.05,.10),(.10,.16),(.16,.23)]:
 f=(w[2]>=a)&(w[2]<bb);q=w[:,f];u=xx[f];v=yy[f];
 print(a,bb,q.shape[1], 'xyz q10/50/90=',np.round(np.percentile(q.T,[10,50,90],axis=0),3) if q.shape[1] else None,'uv=',np.round(np.percentile(np.stack([u,v],1),[10,50,90],axis=0),1) if q.shape[1] else None)
